      available: true,
      station: d.stacja,
      measuredAt: `${d.data_pomiaru ?? ""} ${d.godzina_pomiaru ?? ""}:00`.trim(),
      tempC: d.temperatura ?? "\u2014",
      rainMm: d.suma_opadu ?? "0.0",
